fun testCollections() {
    println("== plus / minus")
    val xs = listOf(1, 2, 3, 2)
    val arr = arrayOf(2, 9)
    val seq = sequenceOf(3, 8)
    println(xs + arr)
    println(xs + seq)
    println(xs - arr)
    println(xs - seq)
    println(xs - listOf(2))
    val col: Collection<Int> = xs
    println(col + arr)
    println(col + seq)
    val it: Iterable<Int> = xs
    println(it + arr)
    println(it + seq)
    println(it - arr)
    println(it - seq)
    val set = setOf(1, 2, 3)
    println(set + arr)
    println(set + seq)
    println(set - arr)
    println(set - seq)
    println(set + listOf(7))
    println(set - listOf(1))
    val s = sequenceOf(1, 2, 3, 2)
    println((s + arr).toList())
    println((s + listOf(5)).toList())
    println((s + seq).toList())
    println((s + 4).toList())
    println((s - arr).toList())
    println((s - listOf(2)).toList())
    println((s - seq).toList())
    println((s - 2).toList())
    val m = mapOf(1 to "a", 2 to "b")
    println(m + (3 to "c"))
    println(m + mapOf(2 to "z"))
    println(m + listOf(4 to "d"))
    println(m + arrayOf(5 to "e"))
    println(m + sequenceOf(6 to "f"))
    println(m - 1)
    println(m - listOf(1, 2))
    println(m - arrayOf(1))
    println(m - sequenceOf(2))
}

fun testAssign() {
    println("== plusAssign / minusAssign")
    val mc = mutableListOf(1, 2, 3, 4)
    mc += arrayOf(5, 6)
    mc += sequenceOf(7)
    mc += listOf(8)
    mc += 9
    println(mc)
    mc -= arrayOf(1, 2)
    mc -= sequenceOf(3)
    mc -= listOf(4)
    mc -= 5
    println(mc)
    val mm = mutableMapOf(1 to "a")
    mm += 2 to "b"
    mm += mapOf(3 to "c")
    mm += listOf(4 to "d")
    mm += arrayOf(5 to "e")
    mm += sequenceOf(6 to "f")
    println(mm)
    mm -= 1
    mm -= listOf(2, 3)
    mm -= arrayOf(4)
    mm -= sequenceOf(5)
    println(mm)
    mm[7] = "g"
    println(mm)
}

fun testContains() {
    println("== mixed contains")
    val r = 1..5
    println(3L in r)
    println(3.toByte() in r)
    println(3.toShort() in r)
    println(9L in r)
    val lr = 1L..5L
    println(3 in lr)
    println(3.toByte() in lr)
    println(3.toShort() in lr)
    println(1.toByte() in 1.toByte()..5.toByte())
    println(3 in 1.toByte()..5.toByte())
    println(3L in 1.toByte()..5.toByte())
    println(3u in 1u..5u)
    println(3u.toUByte() in 1u..5u)
    println(3u.toUShort() in 1u..5u)
    println(3uL in 1uL..5uL)
    println(3u in 1uL..5uL)
    println('c' in 'a'..'e')
    println(3 in 1..<5)
    println(5 in 1..<5)
    println(3L in 1..<5)
    println(listOf(1, 2).contains(2))
    println(listOf<Any?>(1, "a", null).contains(null))
    println(listOf(1, 2, 3).asIterable().contains(3))
    println(sequenceOf(1, 2, 3).contains(4))
}

fun main() {
    testCollections()
    testAssign()
    testContains()
}
